import{_ as r,C as a,o as s,c,E as e,a7 as d}from"./chunks/framework.FWlv_suP.js";const v=JSON.parse('{"title":"Qurio Data Collection","description":"A summary of Qurio data practices.","frontmatter":{"title":"Qurio Data Collection","description":"A summary of Qurio data practices."},"headers":[],"relativePath":"apps/qurio/data-collection.md","filePath":"apps/qurio/data-collection.md"}'),l={name:"apps/qurio/data-collection.md"};function p(u,t,m,h,f,b){const o=a("AppBreadcrumbs"),n=a("AppSubnav"),i=a("CopyStandaloneUrl");return s(),c("div",null,[e(o,{"app-id":"qurio",current:"Data Collection"}),e(n,{"app-id":"qurio"}),e(i,{path:"/data-collection/qurio",label:"Copy standalone data-collection URL","copied-label":"Data Collection URL copied","document-name":"Qurio data-collection page"}),t[0]||(t[0]=d('<h1 id="qurio-data-collection" tabindex="-1">Qurio Data Collection <a class="header-anchor" href="#qurio-data-collection" aria-label="Permalink to &quot;Qurio Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> September 22, 2026</p><h2 id="information-processed" tabindex="-1">Information processed <a class="header-anchor" href="#information-processed" aria-label="Permalink to &quot;Information processed&quot;">​</a></h2><p>Qurio processes a display name, email address, Supabase authentication credentials, email-verification status, account status, and role. Passwords are not available to the developer in plaintext. Account administration may record approval, denial, suspension, reactivation, role changes, reasons, and audit details.</p><p>For approved accounts, Qurio stores language, theme, curriculum, grade, selected exam plan, study progress, content identifiers, quiz attempts and answers, hint use, timing, scores, pass results, exam-plan tasks, bookmarks, and timestamps in Supabase&#39;s hosted PostgreSQL (SQL) database. This is the account&#39;s canonical learning record.</p><h2 id="local-information" tabindex="-1">Local information <a class="header-anchor" href="#local-information" aria-label="Permalink to &quot;Local information&quot;">​</a></h2><p>The app may keep a local authenticated session, display preferences, and a temporary synchronization cache. Local data supports the installation but is not the canonical account record. Optional web PIN protection stores a salted password-derived verifier in IndexedDB. Android biometric unlock uses random unlock material protected by Android Keystore and does not store the PIN; Qurio does not collect biometric templates.</p><p>Enabled reminder days and time are saved to account settings in the Supabase SQL database so they can be restored for that account. The notification-permission state and scheduled notification remain on the Android device. No push-notification token is uploaded.</p><h2 id="account-deletion" tabindex="-1">Account deletion <a class="header-anchor" href="#account-deletion" aria-label="Permalink to &quot;Account deletion&quot;">​</a></h2><p>Learner and Administrator accounts can be permanently deleted in Qurio Settings after confirming the signed-in email address. Deletion removes the authenticated account and its linked profile, account settings, learning records, quiz attempts and answers, bookmarks, and exam-plan progress. The current installation also clears the deleted account&#39;s active session and app-lock data. Owner accounts cannot self-delete until ownership is transferred.</p><p>Minimal audit records and support correspondence may remain where necessary for security, legal duties, disputes, or accountability.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Supabase Authentication and Supabase&#39;s hosted PostgreSQL (SQL) database process authentication, profile, authorization, learning, settings, and audit data. GitHub hosts the web client and learning content. The authentication email provider processes addresses and delivery metadata for verification and password-reset messages. Providers also receive normal connection and security metadata.</p><h2 id="advertising-and-analytics" tabindex="-1">Advertising and analytics <a class="header-anchor" href="#advertising-and-analytics" aria-label="Permalink to &quot;Advertising and analytics&quot;">​</a></h2><p>Qurio has no advertising, developer-operated analytics, or tracking SDK.</p><p>Questions: <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',16))])}const y=r(l,[["render",p]]);export{v as __pageData,y as default};
